document.querySelectorAll('[data-lab="PM04-I1"]').forEach(root=>{const g=k=>root.querySelector('[data-field="'+k+'"]'),zh=root.dataset.lang==='zh';const update=()=>{const x=+g('x').value/100,n=+g('n').value,p=(1-x)**n;g('xout').textContent=(x*100).toFixed(1)+'%';g('nout').textContent=n;g('bar').setAttribute('width',p*550);g('result').textContent=zh?'P = '+(1-x).toFixed(3)+' 的 '+n+' 次方 = '+p.toFixed(4)+'，即 '+(p*100).toFixed(2)+'%。片段越长或共聚概率越高，全部位置保持丙烯的概率越小。这里计算指定序列组成；结晶还需要合适的堆积与时间。':'P = '+(1-x).toFixed(3)+' raised to '+n+' = '+p.toFixed(4)+', or '+(p*100).toFixed(2)+'%. Longer segments or higher comonomer probability reduce the chance of an uninterrupted propylene segment. This calculates sequence composition; crystallization additionally requires packing and time.';};root.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));update();});